"python3 -c "
import subprocess, json
out = subprocess.check_output(['python3', '.agents/plugins/bug-fixer-loop-plugin/scripts/safe_ingest.py', 'issue-list', '--repo', 'matthewmcneill/esp32-app-foundation', '--state', 'open', '--limit', '200', '--json', 'number,title,labels'])
data = json.loads(out)
classification_labels = {
    'bug-fixer:engineer:needs-fix',
    'bug-fixer:human:needs-approach-review',
    'bug-fixer:human:input-needed',
    'bug-fixer:human:project-candidate',
    'bug-fixer:human:required'
}
unclassified = []
for it in data:
    lbls = {l['name'] for l in it.get('labels', [])}
    if not (lbls & classification_labels):
        unclassified.append((it['number'], it['title'], list(lbls)))

print(f'Unclassified count: {len(unclassified)}')
for num, title, lbls in unclassified:
    print(f'#{num}: {title} -> {lbls}')
